resolved as (
    select
        HUB_CLAIM_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then AILMENT_DESCRIPTION end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AILMENT_DESCRIPTION end)) as AILMENT_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AMBULANCE_CHARGES end) as AMBULANCE_CHARGES,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ROOM_RENT_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ROOM_RENT_AMOUNT end)) as ROOM_RENT_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ELIGIBLE_ROOM_CATEGORY end) as ELIGIBLE_ROOM_CATEGORY,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ELIGIBLE_ROOM_RENT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ELIGIBLE_ROOM_RENT end)) as ELIGIBLE_ROOM_RENT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ROOM_CATEGORY end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ROOM_CATEGORY end)) as ROOM_CATEGORY,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ICU_RENT_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ICU_RENT_AMOUNT end)) as ICU_RENT_AMOUNT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then IPD_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then IPD_NUMBER end)) as IPD_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NETWORK_DISCOUNT_AMOUNT end) as NETWORK_DISCOUNT_AMOUNT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CASHLESS_AUTHORISATION_NUMBER end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then CASHLESS_AUTHORISATION_NUMBER end)) as CASHLESS_AUTHORISATION_NUMBER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ADMISSION_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ADMISSION_DATE end)) as ADMISSION_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then HOSPITAL_REFERENCE end) as HOSPITAL_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NETWORK_HOSPITAL_INDICATOR end) as NETWORK_HOSPITAL_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then TREATMENT_TYPE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then TREATMENT_TYPE end)) as TREATMENT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DIAGNOSIS_CODE end) as DIAGNOSIS_CODE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ICD_CODE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ICD_CODE end)) as ICD_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PROCEDURE_CODE end) as PROCEDURE_CODE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then DISCHARGE_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DISCHARGE_DATE end)) as DISCHARGE_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FINAL_BILL_AMOUNT end) as FINAL_BILL_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DISALLOWED_AMOUNT end) as DISALLOWED_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CO_PAY_AMOUNT end) as CO_PAY_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then OTHER_DEDUCTION_AMOUNT end) as OTHER_DEDUCTION_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DISALLOWANCE_REASON end) as DISALLOWANCE_REASON,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ACTUAL_PACKAGE_AMOUNT end) as ACTUAL_PACKAGE_AMOUNT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then EXPECTED_DISCHARGE_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EXPECTED_DISCHARGE_DATE end)) as EXPECTED_DISCHARGE_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SURGERY_INDICATOR end) as SURGERY_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRE_HOSPITALISATION_AMOUNT end) as PRE_HOSPITALISATION_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then OT_CHARGES end) as OT_CHARGES,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PHARMACY_AMOUNT end) as PHARMACY_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MISCELLANEOUS_CHARGES_AMOUNT end) as MISCELLANEOUS_CHARGES_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then POST_HOSPITALISATION_AMOUNT end) as POST_HOSPITALISATION_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PROCEDURE_DESCRIPTION end) as PROCEDURE_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SURGEON_FEE end) as SURGEON_FEE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NURSING_CHARGES end) as NURSING_CHARGES,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ICU_CHARGES_AMOUNT end) as ICU_CHARGES_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then IMPLANT_COST end) as IMPLANT_COST,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRE_AUTHORISATION_AMOUNT end) as PRE_AUTHORISATION_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRE_AUTHORISATION_REMARKS end) as PRE_AUTHORISATION_REMARKS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ANAESTHETIST_FEE end) as ANAESTHETIST_FEE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then INVESTIGATION_CHARGES end) as INVESTIGATION_CHARGES,
        max(case when SOURCE_RUN = 'opus_health_v2' then TREATING_DOCTOR_NAME end) as TREATING_DOCTOR_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then SURGERY_NAME end) as SURGERY_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then ADMISSION_TIME end) as ADMISSION_TIME,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when AILMENT_DESCRIPTION is not null or AMBULANCE_CHARGES is not null or ROOM_RENT_AMOUNT is not null or ELIGIBLE_ROOM_CATEGORY is not null or ELIGIBLE_ROOM_RENT is not null or ROOM_CATEGORY is not null or ICU_RENT_AMOUNT is not null or IPD_NUMBER is not null or NETWORK_DISCOUNT_AMOUNT is not null or CASHLESS_AUTHORISATION_NUMBER is not null or ADMISSION_DATE is not null or HOSPITAL_REFERENCE is not null or NETWORK_HOSPITAL_INDICATOR is not null or TREATMENT_TYPE is not null or DIAGNOSIS_CODE is not null or ICD_CODE is not null or PROCEDURE_CODE is not null or DISCHARGE_DATE is not null or FINAL_BILL_AMOUNT is not null or DISALLOWED_AMOUNT is not null or CO_PAY_AMOUNT is not null or OTHER_DEDUCTION_AMOUNT is not null or DISALLOWANCE_REASON is not null or ACTUAL_PACKAGE_AMOUNT is not null or EXPECTED_DISCHARGE_DATE is not null or SURGERY_INDICATOR is not null or PRE_HOSPITALISATION_AMOUNT is not null or OT_CHARGES is not null or PHARMACY_AMOUNT is not null or MISCELLANEOUS_CHARGES_AMOUNT is not null or POST_HOSPITALISATION_AMOUNT is not null or PROCEDURE_DESCRIPTION is not null or SURGEON_FEE is not null or NURSING_CHARGES is not null or ICU_CHARGES_AMOUNT is not null or IMPLANT_COST is not null or PRE_AUTHORISATION_AMOUNT is not null or PRE_AUTHORISATION_REMARKS is not null or ANAESTHETIST_FEE is not null or INVESTIGATION_CHARGES is not null or TREATING_DOCTOR_NAME is not null or SURGERY_NAME is not null or ADMISSION_TIME is not null
                     then md5(upper(coalesce(cast(AILMENT_DESCRIPTION as varchar), '') || '|' || coalesce(cast(AMBULANCE_CHARGES as varchar), '') || '|' || coalesce(cast(ROOM_RENT_AMOUNT as varchar), '') || '|' || coalesce(cast(ELIGIBLE_ROOM_CATEGORY as varchar), '') || '|' || coalesce(cast(ELIGIBLE_ROOM_RENT as varchar), '') || '|' || coalesce(cast(ROOM_CATEGORY as varchar), '') || '|' || coalesce(cast(ICU_RENT_AMOUNT as varchar), '') || '|' || coalesce(cast(IPD_NUMBER as varchar), '') || '|' || coalesce(cast(NETWORK_DISCOUNT_AMOUNT as varchar), '') || '|' || coalesce(cast(CASHLESS_AUTHORISATION_NUMBER as varchar), '') || '|' || coalesce(cast(ADMISSION_DATE as varchar), '') || '|' || coalesce(cast(HOSPITAL_REFERENCE as varchar), '') || '|' || coalesce(cast(NETWORK_HOSPITAL_INDICATOR as varchar), '') || '|' || coalesce(cast(TREATMENT_TYPE as varchar), '') || '|' || coalesce(cast(DIAGNOSIS_CODE as varchar), '') || '|' || coalesce(cast(ICD_CODE as varchar), '') || '|' || coalesce(cast(PROCEDURE_CODE as varchar), '') || '|' || coalesce(cast(DISCHARGE_DATE as varchar), '') || '|' || coalesce(cast(FINAL_BILL_AMOUNT as varchar), '') || '|' || coalesce(cast(DISALLOWED_AMOUNT as varchar), '') || '|' || coalesce(cast(CO_PAY_AMOUNT as varchar), '') || '|' || coalesce(cast(OTHER_DEDUCTION_AMOUNT as varchar), '') || '|' || coalesce(cast(DISALLOWANCE_REASON as varchar), '') || '|' || coalesce(cast(ACTUAL_PACKAGE_AMOUNT as varchar), '') || '|' || coalesce(cast(EXPECTED_DISCHARGE_DATE as varchar), '') || '|' || coalesce(cast(SURGERY_INDICATOR as varchar), '') || '|' || coalesce(cast(PRE_HOSPITALISATION_AMOUNT as varchar), '') || '|' || coalesce(cast(OT_CHARGES as varchar), '') || '|' || coalesce(cast(PHARMACY_AMOUNT as varchar), '') || '|' || coalesce(cast(MISCELLANEOUS_CHARGES_AMOUNT as varchar), '') || '|' || coalesce(cast(POST_HOSPITALISATION_AMOUNT as varchar), '') || '|' || coalesce(cast(PROCEDURE_DESCRIPTION as varchar), '') || '|' || coalesce(cast(SURGEON_FEE as varchar), '') || '|' || coalesce(cast(NURSING_CHARGES as varchar), '') || '|' || coalesce(cast(ICU_CHARGES_AMOUNT as varchar), '') || '|' || coalesce(cast(IMPLANT_COST as varchar), '') || '|' || coalesce(cast(PRE_AUTHORISATION_AMOUNT as varchar), '') || '|' || coalesce(cast(PRE_AUTHORISATION_REMARKS as varchar), '') || '|' || coalesce(cast(ANAESTHETIST_FEE as varchar), '') || '|' || coalesce(cast(INVESTIGATION_CHARGES as varchar), '') || '|' || coalesce(cast(TREATING_DOCTOR_NAME as varchar), '') || '|' || coalesce(cast(SURGERY_NAME as varchar), '') || '|' || coalesce(cast(ADMISSION_TIME as varchar), '')))
                end as SAT_CLAIM_HEALTH_DETAIL_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_HEALTH_DETAIL_HASHDIFF is not null
